-- #894 work item 4: Chatter Snow's Learn guides move into its own rows.
--
-- The eight categories and thirty-seven articles that were
-- `src/app/(public)/learn/*-data.ts` -- 1,913 lines of one tenant's
-- snow-sports writing compiled into every tenant's bundle -- become
-- `article_categories` and `articles` rows belonging to Chatter Snow, and the
-- files go in the same change.
--
-- **This migration runs before the files are deleted, and that order is the
-- point.** It is the same hazard as #795 rollout step 3: content still falling
-- through to a compiled default at the moment that default disappears loses its
-- copy on the live site. The rows land first; the renderer reads rows from the
-- same commit.
--
-- Scoped by slug, like 20260908040000, 20260908060000 and 20260908070000: the
-- demo and platform tenants must not inherit a nonprofit's content, and on an
-- environment with no `chatter-snow` tenant the CTE matches nothing and this is
-- a no-op. Local development and CI are seeded separately, in
-- supabase/seed.sql.
--
-- Published rather than drafted: this is copy that is already on the live site,
-- so it arrives published, with `published_at` stamped by the trigger. There is
-- deliberately no `on conflict` -- a category slug already present for this
-- tenant means someone has written articles from the portal, and this migration
-- has nothing to add to them.
--
-- Generated from the *-data.ts files rather than retyped.


with tenant as (
  select id from public.tenants where slug = 'chatter-snow'
),
category_rows as (
  insert into public.article_categories (tenant_id, slug, position, value)
  select tenant.id, c.slug, c.position, c.value
  from tenant
  cross join (values
    ('getting-started', 0, '{"title":"Getting Started","description":"New to snow sports? Start here for the basics of your first day on the mountain."}'::jsonb),
    ('gear-and-sizing', 1, '{"title":"Gear & Sizing","description":"What gear you need and how it should fit, from skis and boards to boots and bindings."}'::jsonb),
    ('mountain-basics', 2, '{"title":"Mountain Basics","description":"Reading trail signs, understanding lifts, and finding your way around a resort."}'::jsonb),
    ('budget', 3, '{"title":"Snow Sports on a Budget","description":"Ways to get on the mountain without spending more than you have to."}'::jsonb),
    ('etiquette', 4, '{"title":"Mountain & Lift Etiquette","description":"Unwritten rules for sharing lifts, lines, and trails with everyone else out there."}'::jsonb),
    ('park-riding-safety', 5, '{"title":"Park Riding & Safety","description":"Terrain park etiquette, feature progression, and staying safe out there — with links to the official rules and resources."}'::jsonb),
    ('gear-care', 6, '{"title":"Gear Care","description":"Keeping your equipment in good shape between trips, and knowing when it needs a shop."}'::jsonb),
    ('community-and-inclusion', 7, '{"title":"Community & Inclusion","description":"Finding your place in the snow sports community, whatever that looks like for you."}'::jsonb)
  ) as c(slug, position, value)
  returning id, tenant_id, slug
)
insert into public.articles (tenant_id, category_id, anchor, position, value)
select category_rows.tenant_id, category_rows.id, a.anchor, a.position, a.value
from category_rows
join (values
  ('getting-started', 'first-day', 0, '{"title":"First day guide: what to expect at the mountain","description":"A first day is mostly logistics — parking, tickets, rentals, and finding the right building — long before it''s anything to do with skiing or riding. Here''s the general shape of a day at a resort so less of it is a surprise.","paragraphs":["The first hour or two of the day is when tickets, rentals, and lesson check-in are all busiest at once, so many first-timers find it helps to build in more buffer time than they think they need.","Resort staff are used to first-timers asking where things are — guest services, the ticket window, and ski patrol are all reasonable places to start when you''re not sure where to go.","Lifts stop running before the light goes, and \"last chair\" times are usually posted at the base area and on the resort''s website or app. Conditions and which trails and lifts are actually open change day to day, so a resort''s conditions report is worth checking before the drive rather than after.","The responsibility code that applies on the mountain is published by the National Ski Areas Association and posted at most resorts. Reading it once before your first day is a common way people get oriented to what''s expected of everyone out there."],"list":[{"label":"Arriving & parking","text":"Lots typically fill earliest on weekends and holidays, and larger resorts often run shuttles from overflow lots to the base area. Some mountains reserve closer lots or charge for them on busy days."},{"label":"Tickets & passes","text":"Lift access is usually sold online in advance or at a ticket window, and advance online pricing is commonly lower than walk-up. Whatever you buy gets scanned at the lift, so keep it somewhere reachable."},{"label":"The rental shop","text":"Rental staff generally ask for height, weight, boot size, and how much experience you have, then fit you with equipment. Mornings are the busiest stretch of the day here."},{"label":"The lessons desk","text":"Lessons usually check in at their own desk or meeting spot, which is often a different place than the rental shop. Confirmation emails typically say where and when to show up."},{"label":"The base lodge","text":"Bathrooms, food, somewhere to warm up, and often day lockers for a small fee. It''s the usual place to meet up with the people you came with."},{"label":"The learning area","text":"Most resorts have a dedicated beginner zone with gentle terrain and a slow lift — often a magic carpet, a moving belt you ride standing up — separate from the main trail network."}],"links":[{"label":"NSAA — Your Responsibility Code","href":"https://www.nsaa.org/NSAA/Safety/Your_Responsibility_Code.aspx"},{"label":"Chatter Snow events & mountain days","href":"/events","internal":true}],"disclaimer":"Every mountain runs its base area a little differently, so treat this as the general shape of a first day, not your specific resort''s playbook — their own site or guest services has the real details."}'::jsonb),
  ('getting-started', 'what-to-pack', 1, '{"title":"What to pack for your first day","description":"Rental shops cover the equipment; what you wear and carry is generally on you. This is an overview of what people typically bring and what a resort typically provides.","paragraphs":["A rental package typically covers skis or a snowboard, boots, poles for skiers, and frequently a helmet. Clothing is generally not included, though some resorts and community programs do rent or lend jackets and pants — worth asking about rather than assuming either way.","Rental and clothing prices vary widely by region, resort, and season, and change from year to year, so treat any number you see quoted anywhere as a rough estimate and confirm current pricing with the shop or resort directly.","Borrowing or renting for a first day is common, since it avoids buying gear before you know what you like. Nonprofit gear libraries and community lending programs, including ours, exist partly for that reason.","Nothing here has to be technical or expensive to work — warm, waterproof, and layered is the general idea, and plenty of first-timers get through their first day with borrowed or secondhand clothing."],"list":[{"label":"Layers","text":"A base layer, an insulating mid layer, and a waterproof outer layer is the common approach, because it can be adjusted through the day. Cotton is generally avoided for the layers against your skin since it holds moisture rather than moving it away."},{"label":"Waterproof jacket & pants","text":"Snow melts on contact, and beginners spend more time in it than experienced riders do. Water-resistant is not the same as waterproof, and the difference shows up fastest while learning."},{"label":"Gloves or mittens","text":"Waterproof, and warm enough for the forecast rather than the parking lot. A spare pair is a common thing to leave in the car or a locker, since wet gloves rarely dry during the day."},{"label":"Goggles & sun protection","text":"UV exposure is stronger at altitude and reflects back off the snow, so sunscreen and eye protection matter even on overcast days. Goggles also handle wind and falling snow in a way sunglasses don''t."},{"label":"Helmet","text":"Rental packages often include one, and many people bring their own. Fit is what makes a helmet work, so a shop or rental technician is the right person to check it."},{"label":"Socks","text":"One pair of tall socks made for ski or snowboard boots is the usual setup. Doubling up socks tends to make boots tighter rather than warmer."},{"label":"ID & payment","text":"Rental shops generally need identification and a card on file, and lessons or tickets may need a confirmation number."},{"label":"Water, snacks & small extras","text":"Lip balm, a snack, and water are easy to forget. A day locker or a small backpack covers whatever you don''t want to carry on the lift."}],"links":[{"label":"Chatter Snow gear library","href":"/gears/library","internal":true},{"label":"Equipment sizing guide","href":"/gears/sizing","internal":true}],"disclaimer":"Consider this a packing checklist, not a shopping list for particular brands. Any prices here are ballpark — check current numbers with the resort or shop — and for what actually suits the day''s conditions, the forecast and whoever''s fitting your gear will know better than an article."}'::jsonb),
  ('getting-started', 'skiing-101', 2, '{"title":"Skiing 101: the absolute basics","description":"What skiing actually involves at a concept level — the equipment, the vocabulary, and how people typically get started. This is orientation, not instruction: the physical technique belongs in a lesson.","paragraphs":["A typical first day on skis stays in a learning area on very gentle terrain, working on balance, sliding, controlling speed, stopping, and eventually turning. Instructors usually introduce those in an order that builds on itself, which is a large part of what you''re paying for in a lesson.","How quickly any of that comes together varies enormously between people, and comparing your first day to someone else''s is generally not a useful measure of anything.","Skiing is physically demanding in ways that are easy to underestimate — cold, altitude at many resorts, and muscles used differently than usual. Taking breaks, drinking water, and stopping while you still have something left are common pieces of advice from instructors and patrollers.","Anything involving actual technique, terrain choice for your ability, or binding settings is a conversation for a certified instructor or a shop technician who can see your equipment and watch you ride. An article can tell you what the pieces are; it can''t tell you what to do with your body or your gear."],"list":[{"label":"Skis","text":"Two separate boards, one per foot. Length and shape vary with a rider''s height, weight, and the kind of terrain the ski is built for, which is why rental shops ask for measurements."},{"label":"Boots","text":"Stiff plastic shells that hold the ankle and lower leg and transfer movement to the ski. They fit far more snugly than normal footwear, and a boot fitter is the right person to sort out fit problems."},{"label":"Bindings","text":"The mechanism connecting boot to ski, designed to release the boot under certain forces. The release setting (often called DIN) depends on several rider-specific factors and is set and tested by a certified technician — never adjusted by the rider."},{"label":"Poles","text":"Used for timing, balance, and pushing along flat sections. Some beginner lessons start without them so there''s less to manage at once."},{"label":"Trail ratings","text":"In North America, green circle, blue square, and black diamond mark relative difficulty within a single resort — they''re not standardized between mountains, so a green at one resort may not feel like a green at another."},{"label":"Groomers","text":"Trails machine-smoothed overnight into a consistent corduroy-like surface. They''re the most predictable terrain on the mountain and where most learning happens."}],"links":[{"label":"Equipment sizing guide","href":"/gears/sizing","internal":true},{"label":"NSAA — Your Responsibility Code","href":"https://www.nsaa.org/NSAA/Safety/Your_Responsibility_Code.aspx"}],"disclaimer":"Think of this as the lay of the land, not a lesson. Actual technique is something a certified instructor should walk you through in person — and binding release settings always belong with a shop tech, never a website."}'::jsonb),
  ('getting-started', 'snowboarding-101', 3, '{"title":"Snowboarding 101: the absolute basics","description":"The same orientation, snowboard-specific: what the equipment is, how the vocabulary works, and what the first day generally looks like. Technique itself is left to instructors.","paragraphs":["First days on a snowboard generally stay in a learning area, covering how to strap in, how to stand up, how to slide and control speed on one edge, and how to stop. Instructors introduce those in a sequence, and falling is a normal part of the process rather than a sign it''s going badly.","Because falls while learning often go onto hands and wrists, wrist guards are common among new snowboarders, and helmets are close to standard across the sport. Whether particular protective gear suits you is worth discussing with an instructor or shop rather than deciding from an article.","Skiing and snowboarding tend to feel different in the early stages — people often describe snowboarding as harder in the first days and skiing as harder to progress in later on — but that''s a generalization with plenty of exceptions, not a rule to plan around.","As with skiing, actual technique and terrain choice come from a lesson or an experienced instructor who can watch you ride. What''s here is meant to make the first day less unfamiliar, not to teach you to ride."],"list":[{"label":"The board","text":"A single board with both feet mounted across it, facing sideways. Length and width vary with rider size and the terrain the board is built for, which is why rental shops ask for measurements."},{"label":"Boots","text":"Usually softer and more flexible than ski boots, though still far snugger than everyday footwear. Fit is the thing that matters most, and a boot fitter is the right person to sort it out."},{"label":"Bindings","text":"Strap or attach each boot to the board. Unlike ski bindings, standard snowboard bindings are not designed to release, so there''s no rider-adjustable release setting to think about — mounting and setup are still a shop''s job."},{"label":"Stance","text":"Riding left-foot-forward is called regular and right-foot-forward is called goofy. Neither is better; which one feels natural varies by person, and instructors and rental staff have ways of helping people figure out their own."},{"label":"Riding lifts","text":"Snowboarders unstrap their back foot to load and unload lifts, then push along flat sections with it — often called skating. It''s one of the more distinctly awkward parts of the first day for most people."},{"label":"Trail ratings","text":"Green circle, blue square, and black diamond mark relative difficulty within one resort, not across resorts. Beginner terrain and learning areas are usually mapped separately from the main trail network."}],"links":[{"label":"Equipment sizing guide","href":"/gears/sizing","internal":true},{"label":"NSAA — Your Responsibility Code","href":"https://www.nsaa.org/NSAA/Safety/Your_Responsibility_Code.aspx"}],"disclaimer":"Consider this the map, not the lesson. For actual technique, equipment setup, or what protective gear makes sense for you, that''s a certified instructor or a shop talking — not a webpage."}'::jsonb),
  ('getting-started', 'lesson-vs-going-it-alone', 4, '{"title":"Booking a lesson vs. going it alone","description":"Both routes are common, and which one fits depends on your situation. These are the factors people generally weigh — not a recommendation either way.","paragraphs":["The trade-off most people are actually weighing is cost and flexibility against structure and terrain management. Neither side of that is the objectively right answer, and plenty of people mix the two — a lesson on day one, friends after that, or the reverse.","If cost is the constraint, it''s worth knowing that beginner packages, weekday rates, off-peak timing, and community programs all exist specifically to lower it. Nonprofit and community organizations, ours included, run mentorship and beginner sessions in that space.","Whichever route you take, the responsibility code applies the same way, and ski patrol is the resource for anything that goes wrong on the mountain. Choosing terrain within your current ability is the piece an instructor would otherwise be handling for you.","If you''re deciding for someone else — a child, or a first-timer in your group — resorts and programs usually have age minimums and their own formats for younger beginners, so their guest services or programs desk is the place to confirm what''s actually available."],"list":[{"label":"What a lesson usually includes","text":"A qualified instructor, a structured progression, and terrain chosen for your level. Beginner packages at many resorts bundle a lesson with a lift ticket and rentals."},{"label":"Group vs. private","text":"Group lessons cost less per person and move at the group''s pace; private lessons cost more and move at yours. Both are typically booked in advance, and beginner slots often fill on weekends and holidays."},{"label":"Cost","text":"Lessons are usually the largest single line item on a first day, and prices vary widely by resort, season, and format. Treat any figure you find as an estimate and confirm current pricing with the resort."},{"label":"Going with an experienced friend","text":"Free, familiar, and flexible — but a friend who rides well isn''t necessarily trained to teach, and a common failure mode is being taken onto terrain that''s beyond a first-timer''s comfort."},{"label":"Learning on your own","text":"Possible on beginner terrain, and some people prefer it. It does mean nobody is managing terrain choice or pacing for you, which is the part that most often goes wrong early on."},{"label":"Time & scheduling","text":"Lessons run on set times and check-in windows; unstructured days don''t. If your group has one car and one schedule, that''s often the deciding practical factor."}],"links":[{"label":"Chatter programs — mentorship & beginner sessions","href":"/programs","internal":true},{"label":"NSAA — Your Responsibility Code","href":"https://www.nsaa.org/NSAA/Safety/Your_Responsibility_Code.aspx"}],"disclaimer":"These are the trade-offs to weigh, not a verdict on how you should learn. Lesson formats, age minimums, and pricing all shift by resort and season, so treat any numbers here as ballpark and let the resort confirm what''s actually on offer."}'::jsonb),
  ('gear-and-sizing', 'gear-101', 0, '{"title":"Gear 101: what you actually need for your first day","description":"A first day on snow involves more gear than it might seem from the outside. Here''s the general breakdown of what''s typically needed, and what''s usually provided if you''re taking a lesson or renting.","paragraphs":["Most first-timers rent the big-ticket items — skis or a board, boots, bindings, and often a helmet — rather than buying, since sizing and preferences are still unknown at that point. A resort or shop rental package typically covers all of that in one transaction.","What people usually already own or borrow is the layering system: base layers, a mid layer, waterproof outerwear, gloves, and a warm hat for the lodge. If you don''t have waterproof outerwear yet, some shops rent jackets and pants too.","If you''re booking a lesson, check what''s included — many first-timer lesson packages bundle rental gear and a lift ticket with instruction, which can be simpler than sourcing everything separately."],"list":[{"label":"Skis or a snowboard, boots, and bindings","text":"The core equipment — usually rented as a package for a first day, since it''s mounted and sized together at the shop."},{"label":"A helmet","text":"Widely rented alongside skis or a board, and increasingly the norm rather than the exception at most resorts."},{"label":"Goggles","text":"Protects eyes from wind, sun glare, and snow spray, and matters more than sunglasses once you''re moving or it''s snowing."},{"label":"Outerwear: a waterproof jacket and pants","text":"Everyday winter coats often aren''t waterproof enough for sitting in snow or falling. Look for gear specifically described as waterproof, not just water-resistant."},{"label":"Base and mid layers","text":"Moisture-wicking base layers plus an insulating mid layer, rather than one heavy layer — it''s easier to regulate temperature by adding or removing pieces."},{"label":"Gloves or mittens, and thick socks","text":"Waterproof gloves or mittens rated for snow, and a single pair of tall, non-cotton ski socks — extra socks tend to make boots fit worse, not warmer."},{"label":"Sun protection","text":"Sunscreen and lip balm — sun exposure is stronger at altitude and reflects off snow, so it adds up faster than it feels like on a cold day."}],"links":[{"label":"Buying vs. renting: how to decide","href":"#buying-vs-renting","internal":true},{"label":"Chatter gear library","href":"/gears/library","internal":true}],"disclaimer":"Take this as a starting checklist, not a personalized packing list — your rental shop or the resort''s own first-timer guidance will know exactly what''s included and what''s on you to bring."}'::jsonb),
  ('gear-and-sizing', 'buying-vs-renting', 1, '{"title":"Buying vs. renting: how to decide","description":"Whether to rent or buy usually comes down to how often you expect to ride and how settled your preferences are, more than a fixed rule.","paragraphs":["There''s no single day count or budget where renting stops making sense and buying starts — it depends on how much storage and maintenance you''re willing to take on, and how confident you are in your gear preferences so far.","Buying used or through a gear library is a common middle path: lower upfront cost than new gear, with less long-term commitment than a full retail purchase. See the used and secondhand gear article below for what to check.","If cost is the main thing keeping you off the mountain, Chatter''s gear library and similar community programs exist specifically to lower that barrier — it''s worth checking what''s available before assuming a purchase is required."],"list":[{"label":"Renting suits occasional riders","text":"If you''re not sure yet how often you''ll get out, renting avoids storage, maintenance, and the cost of gear you might outgrow in ability or preference."},{"label":"Renting suits still-developing preferences","text":"Ski and board feel, length, and flex are personal — renting a few times lets you try different setups before committing to a purchase."},{"label":"Buying suits frequent riders","text":"Once you''re out often enough, rental costs across a season can add up to more than owning, and having your own gear means it''s already sized and broken in."},{"label":"Boots are the exception","text":"Even people who rent everything else often buy boots first, since a well-fitted boot takes time to find and rental boots are rarely as dialed in as an owned pair."},{"label":"Season and multi-day rentals exist","text":"Many shops offer season-long or multi-day rental rates that land between a single-day rental and buying outright, worth asking about if you expect to ride more than a handful of days."}],"links":[{"label":"Used & secondhand gear: what to check for","href":"#used-and-secondhand-gear","internal":true},{"label":"Chatter gear library","href":"/gears/library","internal":true}],"disclaimer":"These are the general tradeoffs, not a verdict for your specific situation — a rental shop can also give you real local pricing to weigh against buying."}'::jsonb),
  ('gear-and-sizing', 'skis-vs-snowboard', 2, '{"title":"Skis vs. snowboard: choosing your sport","description":"Neither sport is objectively easier — they just have different learning curves and feel. This is a general comparison, not a push toward either one.","paragraphs":["People sometimes choose based on what feels more natural in related activities — skateboarding, surfing, or wakeboarding backgrounds sometimes translate toward snowboarding, while general athletic coordination doesn''t strongly predict either way.","Physical factors like knee or ankle sensitivity can also factor in, since the two sports load joints differently, but that''s worth a conversation with a doctor or physical therapist if it''s a real concern, not something to self-diagnose from an article.","Trying both — through a lesson or a friend''s gear — before committing to buying is a reasonable way to decide, since personal feel matters more here than any general comparison."],"list":[{"label":"Skiing: feet move independently","text":"Each foot has its own ski, which often means a shorter path to basic mobility — turning, stopping, and getting on and off lifts tend to click sooner for many beginners."},{"label":"Skiing: linking turns takes longer to refine","text":"Comfortable, controlled skiing on varied terrain often takes longer to build than the initial basics, even though those basics come quickly."},{"label":"Snowboarding: both feet are fixed to one board","text":"This usually means more falling in the first day or two while your body learns to balance sideways, since there''s no independent-leg recovery the way there is on skis."},{"label":"Snowboarding: often clicks faster once balance is there","text":"Many riders find that once the initial balance and falling phase passes, linking turns and general control comes together relatively quickly."},{"label":"Both involve a real first-day learning curve","text":"Neither sport is picked up in a single session for most people — a lesson helps with either one, and expecting some falling and frustration on day one is normal for both."}],"links":[{"label":"Chatter programs — mentorship & beginner sessions","href":"/programs","internal":true}],"disclaimer":"This is a general comparison, not a personal verdict — how each sport actually feels varies wildly person to person, and a lesson is the fastest way to find out for yourself."}'::jsonb),
  ('gear-and-sizing', 'binding-din-settings', 3, '{"title":"Understanding binding DIN settings","description":"DIN (release setting) is how much force it takes for your binding to pop off in a fall. It comes from several factors together, never just one — so leave the actual number to a certified binding tech, not a chart.","paragraphs":["DIN charts exist and are sometimes visible in shops or online, but they''re a starting reference for a technician''s judgment, not a lookup table for skiers to set their own bindings from. A shop visit for binding setup is standard, not optional, when you get new or different gear.","Boot sole compatibility matters alongside the DIN number: GripWalk (rockered) soles need GripWalk-compatible or MNC bindings, while flat ISO 5355 soles need standard alpine bindings. A technician checks this fit as part of setting the binding, not as a separate step you need to figure out yourself.","If a binding releases unexpectedly, feels loose, or doesn''t release when it should, that''s a shop visit, not a DIY adjustment — release settings drift and should be re-tested periodically, especially after a hard impact."],"list":[{"label":"What DIN measures","text":"A numeric release-force setting on alpine ski bindings, balancing retention (staying locked in while skiing) against release (coming free in a fall to help prevent injury)."},{"label":"What it depends on","text":"Skier weight, height, age, boot sole length, and skier type (how cautiously or aggressively you ski) — a technician weighs all of these together, not weight alone."},{"label":"Skier type categories","text":"Bindings are typically set relative to a Type I (cautious), Type II (average), or Type III (aggressive) profile, which reflects riding style and risk tolerance as much as ability."},{"label":"Snowboard bindings are different","text":"Snowboard bindings don''t use a DIN release system the same way alpine ski bindings do — this concept is specific to skiing."}],"links":[{"label":"Ski sizing & binding DIN reference","href":"/gears/sizing","internal":true}],"disclaimer":"None of this is a setting recommendation — it''s just what DIN is and what feeds into it. The actual number always comes from a certified binding tech working with your specific gear, not a chart and not this page."}'::jsonb),
  ('gear-and-sizing', 'helmets-and-protective-gear', 4, '{"title":"Helmets & protective gear basics","description":"An overview of the protective gear people commonly wear on snow and roughly what each piece helps with — not medical guidance, and not a stand-in for a proper fitting.","paragraphs":["Helmet fit matters as much as wearing one at all — an oversized or loosely strapped helmet doesn''t protect the way a properly fitted one does. A shop can help fit a helmet the same way they''d fit boots.","Helmets are generally treated as single-impact items: after a significant crash, the protective foam may be compromised even without visible damage, and manufacturers publish recommended replacement intervals regardless of impacts. See the gear care article on knowing when gear needs replacing for more.","We''re just covering what''s out there, not giving medical advice — got a specific condition or injury history? Loop in a doctor. Someone actually hurt? Get them to ski patrol or a medical pro, not this page."],"list":[{"label":"Helmets","text":"Widely worn at this point and required by many resorts in lessons, rental packages, and terrain parks. A helmet should fit snugly without pressure points and sit level, covering the forehead without tilting back."},{"label":"Goggles or eye protection","text":"Protects against wind, glare, and flying snow — most helmets are designed to pair with goggles rather than sunglasses for a secure, gap-free fit."},{"label":"Wrist guards","text":"Common for snowboarders, especially beginners, since wrists are one of the more frequently injured areas when learning to fall on a board."},{"label":"Impact shorts and padding","text":"Padded shorts, knee pads, or a back protector are worth considering for beginners and park riders, where falls tend to be more frequent or less predictable."},{"label":"Neck gaiters and face protection","text":"Helps with wind and cold on exposed lifts and colder days, more a comfort item than a safety one."}],"links":[{"label":"Knowing when gear needs replacing","href":"/learn/gear-care","internal":true}],"disclaimer":"Nothing here is medical or safety-certification guidance — for fit and what''s actually right for you, ask a shop, and for any real injury, that''s ski patrol or a medical professional, full stop."}'::jsonb),
  ('gear-and-sizing', 'used-and-secondhand-gear', 5, '{"title":"Used & secondhand gear: what to check for","description":"Buying used is a common way to get on snow for less, but a few things are worth checking before handing over money — especially anything safety-related.","paragraphs":["For skis, boards, and boots, a quick look-over by a shop before you buy — or shortly after — can catch issues that aren''t obvious to a non-expert, especially delamination and binding compatibility.","Gear swaps, community sales, and gear libraries are common sources for used equipment. Chatter''s gear library is one option if you''d rather borrow than buy at all.","Fit still matters as much on used gear as new — a good deal on boots or a helmet that doesn''t actually fit isn''t a good deal. Try things on rather than buying by size number alone where possible."],"list":[{"label":"Boots: check the liners and shell","text":"Packed-out liners (compressed and no longer supportive) are hard to spot without trying them on. Look for cracks in the plastic shell and check that buckles still hold tension."},{"label":"Skis and boards: check the base and edges","text":"Look for deep gouges (down to the core material, not just surface scratches), delamination (separating layers, often visible as bubbling or a soft spot), and heavily rusted or nicked edges."},{"label":"Bindings: check they''re on an indemnified list","text":"Shops maintain lists of bindings they''ll still test and service. If a shop won''t work on a binding, it''s effectively at the end of its usable life regardless of how it looks — worth asking a shop before buying gear with existing bindings."},{"label":"Helmets: generally avoid buying used","text":"Impact history usually isn''t visible or known for a used helmet, and helmets are typically treated as single-impact items — this is one category where new is the safer default."},{"label":"Outerwear: check zippers, seams, and water repellency","text":"Worn-through fabric, failed taped seams, and broken zippers are harder to fix than a worn-off water-repellent finish, which can often be renewed."}],"links":[{"label":"Buying vs. renting: how to decide","href":"#buying-vs-renting","internal":true},{"label":"Chatter gear library","href":"/gears/library","internal":true}],"disclaimer":"These are things worth checking, not a guarantee of any item''s condition or safety — for bindings and anything safety-relevant, a shop tech''s actual assessment beats an eyeball check every time."}'::jsonb),
  ('mountain-basics', 'trail-ratings', 0, '{"title":"Trail ratings explained: green, blue, black & beyond","description":"Trail ratings are a resort''s own shorthand for how hard its runs are relative to each other. Understanding what the symbols mean — and what they don''t — is one of the first things that makes a trail map readable.","paragraphs":["The most important thing to know about ratings is that they are relative to the mountain you''re standing on, not standardized across the industry. A blue at a small local hill and a blue at a large mountain out west can be very different runs, and the same is true from region to region and country to country.","Ratings also describe terrain, not conditions. A groomed black in soft snow and the same run scraped down to firm, icy snow late in the day are two different experiences, and the sign at the top says the same thing either way.","Some resorts add their own variations — double green, double blue, a black-diamond-with-an-exclamation for extreme terrain — and those are local conventions rather than a wider standard. The trail map legend is the place to check what a given symbol means at that mountain.","As a way to get oriented on an unfamiliar mountain, it''s common to ride a run one tier easier than what you''re used to first, and use it to calibrate how that resort grades its terrain. An instructor or someone who knows the mountain well can also tell you which specific runs are the friendlier ones in a category."],"list":[{"label":"Green circle — easiest","text":"The gentlest terrain a mountain grooms, usually wide and low-angle. This is where most lessons and first days happen."},{"label":"Blue square — more difficult","text":"Steeper and often narrower than green terrain, typically still groomed. The widest category at most resorts, so blues can vary a lot from run to run."},{"label":"Black diamond — most difficult","text":"Steep, and frequently ungroomed, narrow, or a mix of both. Conditions matter more here than on gentler terrain."},{"label":"Double black diamond — expert only","text":"The steepest and most consequential terrain a resort marks, often with obstacles, cliffs, or mandatory line choices."},{"label":"Terrain park markings","text":"Parks use an orange oval and grade features by size (small, medium, large) rather than by trail difficulty."}],"links":[{"label":"NSAA — Your Responsibility Code","href":"https://www.nsaa.org/NSAA/Safety/Your_Responsibility_Code.aspx"},{"label":"Chatter learn — getting started","href":"/learn/getting-started","internal":true}],"disclaimer":"Ratings are set resort by resort and only make sense relative to that mountain — they''re not standardized, and they say nothing about the day''s actual conditions. When in doubt, the map legend and ski patrol know more than a general guide does."}'::jsonb),
  ('mountain-basics', 'trail-map', 1, '{"title":"Reading a trail map","description":"A trail map packs a lot into one sheet: difficulty, lift lines, base areas, and the routes that connect them. Knowing how to read one makes it much easier to plan a day and to find your way back.","paragraphs":["Most printed trail maps are illustrations rather than to-scale drawings. Artists flatten and rotate faces of the mountain so everything fits on one panel, which means distances and steepness are hard to judge from the picture alone — a run that looks short on paper can be a long ride, and vice versa.","A useful habit is to pick out the return route to your base area before you head up, especially at a mountain with multiple faces or base villages. Some runs only lead back to one side, and the connection you need may be a specific traverse or a last lift with an earlier closing time.","Most resorts now have the same map in an app or on a mobile site, sometimes with lift status, grooming reports, and current openings layered on. That''s often more current than a paper map printed at the start of the season, though phone batteries drain quickly in the cold, so plenty of people carry the paper version too.","If you''re piecing together a route on an unfamiliar mountain, lift operators and ski patrol are used to the question and can tell you which runs actually connect the way you''re hoping."],"list":[{"label":"Legend","text":"Usually a corner box explaining every symbol on the map — difficulty markers, lift types, terrain parks, patrol stations, and food or restroom locations."},{"label":"Lifts","text":"Drawn as lines with their own symbols and names or numbers. The map generally shows where each one starts and ends, which is how you plan a route between areas."},{"label":"Base areas and lodges","text":"Your reference points for meeting people, warming up, and finding services. Larger mountains often have several, and they may not be walkable from one another."},{"label":"Ski patrol and first aid","text":"Marked with a cross or patrol symbol. Worth noting before you need it."},{"label":"Boundary lines","text":"Mark the edge of the patrolled ski area. Beyond them, the terrain isn''t managed, marked, or patrolled the same way."}],"links":[{"label":"Chatter learn — mountain & lift etiquette","href":"/learn/etiquette","internal":true},{"label":"NSAA — Your Responsibility Code","href":"https://www.nsaa.org/NSAA/Safety/Your_Responsibility_Code.aspx"}],"disclaimer":"This covers how trail maps tend to be laid out, not any one resort''s actual map. Every mountain draws its own, on its own schedule, so lean on the current map, app, and posted info for anything you''re actually relying on."}'::jsonb),
  ('mountain-basics', 'lift-types', 2, '{"title":"Lift types & how to ride them","description":"Uphill transport comes in a handful of common forms, and each one loads a little differently. Here''s what you''re likely to run into and what generally distinguishes them.","paragraphs":["Loading is where most lift trouble happens, and the fix is usually just information: watch a cycle or two from the line, read the posted signs at the loading zone, and tell the lift operator it''s your first time on that lift. Operators can slow or stop most lifts and do it routinely — asking is normal, not an imposition.","Surface lifts catch a lot of people out because they tow rather than carry. The general idea is that you''re being pulled along while your equipment stays on the snow, rather than sitting down on anything, and snowboarders ride them with one foot out. How that actually feels is easier to learn from an instructor or an experienced friend than from a description.","On chairlifts, the common norms are to lower the safety bar if the chair has one and others agree, keep loose items and clothing clear of the seat and bar, and stay seated until the unloading ramp. If something does go wrong at unloading, moving clear of the ramp quickly matters most, because the next chair is right behind.","Lifts also close before the mountain does, and last-ride times differ from lift to lift. On a big mountain, missing the last connecting lift can leave you a long way from your base area."],"list":[{"label":"Magic carpet","text":"A conveyor belt at snow level, used on beginner terrain. You stand on it and ride up; nothing to grab or sit on."},{"label":"Rope tow / handle tow","text":"A moving rope or a series of handles that pull you uphill while you stay on your skis or board. Common on small learning slopes."},{"label":"Surface lifts (platter, T-bar, J-bar)","text":"A disc or bar that you brace against and that tows you up the hill. You stay standing on your equipment rather than sitting, and they''re a common substitute for chairs on low-angle or wind-exposed terrain."},{"label":"Chairlift","text":"The most common type — a bench that scoops you up from a loading zone and carries you over the terrain. Ranges from slow doubles to high-speed detachable six-packs, and many have a safety bar overhead."},{"label":"Gondola and tram","text":"Enclosed cabins. Gondolas run continuously in small cabins and usually require removing skis or your board; trams are large cabins running on a fixed schedule."}],"links":[{"label":"Chatter learn — mountain & lift etiquette","href":"/learn/etiquette","internal":true},{"label":"Chatter programs — lessons & mentorship","href":"/programs","internal":true}],"disclaimer":"This covers the common lift types, not how to actually ride one. For loading and unloading technique, an instructor, an experienced friend, or the lift operator will teach you better than a page can — and whatever''s posted at the lift wins regardless."}'::jsonb),
  ('mountain-basics', 'terrain-types', 3, '{"title":"Terrain types: groomed, moguls, trees & backcountry basics","description":"Beyond difficulty ratings, runs differ in what the snow surface itself is like. These categories explain most of what you''ll see described on a trail map or in a grooming report.","paragraphs":["Groomed terrain is where most people spend most of their time, and it''s the surface trail ratings implicitly assume. When a run is left ungroomed, the same slope can feel considerably harder, which is part of why a grooming report is worth a look before you head up.","Tree runs carry hazards that groomed terrain doesn''t, including tree wells — the void of loose, unconsolidated snow that forms around the base of a conifer, which a person can fall into. Riding with a partner and keeping each other in sight is the standard advice you''ll see from patrol and safety organizations for that reason.","Backcountry travel sits well outside the scope of an orientation article. It involves avalanche terrain assessment, rescue equipment and the training to use it, weather and snowpack knowledge, and route-finding — the kind of thing people learn through recognized avalanche courses and time with experienced partners, not from reading. Snow that''s within a ski area boundary has been assessed and mitigated by patrol; the same-looking slope on the other side of a boundary rope has not.","If a type of terrain is new to you, the ordinary way in is a lesson, a guided group, or a day with someone who knows the mountain — and ski patrol can tell you what''s open and what current conditions are like."],"list":[{"label":"Groomed runs","text":"Snow tilled and smoothed overnight by grooming machines, leaving the corduroy-textured surface you see first thing in the morning. The most predictable surface on the mountain."},{"label":"Moguls","text":"Fields of snow bumps that form where skiers repeatedly turn on ungroomed terrain. Rhythmic and demanding, and the shape changes through the day as more people ride them."},{"label":"Tree runs / glades","text":"Marked runs through spaced trees. Visibility is short, the snow surface is uneven, and hazards like stumps, rocks, and tree wells can sit under the snow."},{"label":"Powder and off-piste","text":"Ungroomed snow inside the ski area boundary, patrolled but not smoothed. Depth and quality change quickly with weather and traffic."},{"label":"Backcountry / out-of-bounds","text":"Terrain outside the ski area boundary. Not patrolled, not avalanche-mitigated, and not marked — a fundamentally different activity from resort riding, with its own required training and equipment."}],"links":[{"label":"NSAA — Your Responsibility Code","href":"https://www.nsaa.org/NSAA/Safety/Your_Responsibility_Code.aspx"},{"label":"Chatter programs — lessons & mentorship","href":"/programs","internal":true},{"label":"Chatter learn — park riding & safety","href":"/learn/park-riding-safety","internal":true}],"disclaimer":"This describes terrain types in general, not any specific slope on any specific day. Backcountry and out-of-bounds travel especially needs real avalanche education, proper gear, and experienced partners — a recognized avalanche course is the actual preparation, not this page."}'::jsonb),
  ('mountain-basics', 'signage-and-closures', 4, '{"title":"Mountain signage & closures: what they mean","description":"Signs, ropes, and markers are how a mountain communicates with everyone on it. Most of it is consistent enough across resorts to be worth recognizing on sight.","paragraphs":["Closures usually exist for a reason you can''t see from the top: avalanche mitigation in progress, thin cover or exposed hazards, snowmaking or grooming operations, an incident being managed, or wind damage. The reason isn''t always posted, and patrol generally won''t have time to explain it in the moment.","Ducking a rope is treated seriously by resorts. Beyond the risk to yourself, it can put patrol in the position of running a rescue in terrain they''ve closed, and it commonly results in a pass being pulled — many mountains state this explicitly on the sign or in their pass conditions.","Signage also changes through the day and the season. Runs open and close with conditions, hazard markers move as coverage changes, and a run that was open yesterday may not be today. Grooming and lift-status reports, whether posted at the base or in the resort''s app, are the current picture.","If a sign is unclear, or a rope''s position doesn''t seem to match what''s on your map, ski patrol or a lift operator is the right person to ask. Reporting a hazard you come across — a downed rope, an exposed rock, someone in trouble — to patrol is also part of how the system works."],"list":[{"label":"Difficulty signs","text":"Posted at the top of runs and at junctions, matching the symbols on the trail map. They mark where a run starts and what the resort rates it."},{"label":"Slow zones","text":"Marked areas — often near base areas, lift lines, and merges — where the mountain asks everyone to reduce speed. Resorts do enforce these."},{"label":"Closure ropes and signs","text":"A rope, fence, or sign marking terrain that is closed. Closed means closed, regardless of how the snow looks from outside the rope."},{"label":"Hazard markers","text":"Bamboo poles, crossed poles, padding, or coloured flags marking rocks, thin cover, snowmaking equipment, or other obstacles."},{"label":"Boundary markers","text":"Signs and ropes at the edge of the patrolled ski area, usually stating that terrain beyond is unpatrolled and unmitigated."}],"links":[{"label":"NSAA — Your Responsibility Code","href":"https://www.nsaa.org/NSAA/Safety/Your_Responsibility_Code.aspx"},{"label":"Chatter learn — mountain & lift etiquette","href":"/learn/etiquette","internal":true}],"disclaimer":"Signage conventions shift between resorts, regions, and countries, so treat this as background, not any mountain''s official rulebook. Whatever''s posted, roped off, or said by ski patrol at your actual mountain always wins over anything written here."}'::jsonb),
  ('budget', 'what-it-costs', 0, '{"title":"What skiing and snowboarding actually cost","description":"Snow sports have a reputation for being expensive, and the sticker prices are a big part of why. Here''s a plain breakdown of where the money actually goes on a typical day out. Every figure below is a rough estimate as of the 2025–26 seasons in North America — prices vary enormously by region, resort, and how far ahead you buy, so treat these as orders of magnitude rather than quotes.","paragraphs":["Added up at full price, a first day at a large resort with rentals and a lesson can land in the several-hundred-dollar range per person. That number is real, but it''s also close to the worst case — nearly every line item above has a cheaper version, and the articles in this category walk through them.","The rough shape of it: a day at a small local hill with off-mountain rentals and borrowed clothing can come in at a small fraction of a full-price destination day. Same sport, very different bill.","Costs also change with how much you go. Day tickets are the most expensive way to ski per day, rentals stop making sense at some point if you''re out often, and season passes only pay off past a certain number of days — which is why it''s worth having a rough sense of how many days you actually expect to ride before committing to anything.","Chatter Snow''s programs and gear library exist partly to take some of these numbers off the table for people they''d otherwise price out. If cost is the thing standing between you and a first day, that''s worth a look."],"list":[{"label":"Lift ticket","text":"Usually the single biggest line item. Walk-up window prices at large destination resorts have typically run somewhere in the $100–$250 range per day, while smaller local hills are often a fraction of that — commonly under $75, and sometimes well under. Buying online in advance is generally cheaper than at the window."},{"label":"Rentals","text":"A full ski or snowboard package — boards or skis, boots, and poles where applicable — typically runs somewhere around $40–$70 a day at a resort shop, and often less at an off-mountain shop in the nearest town."},{"label":"Lessons","text":"Group lessons are usually bundled with a beginner ticket-and-rental package; standalone group lessons typically fall in the $75–$200 range, and private instruction is generally several times that."},{"label":"Clothing","text":"Not a per-day cost, but a real one the first season. A jacket, snow pants, gloves, goggles, and base layers bought new typically add up to a few hundred dollars, though this is one of the easiest categories to cover secondhand or by borrowing."},{"label":"Getting there and being there","text":"Fuel or transit, parking (some resorts now charge for it or require a reservation), food, and lodging if it''s not a day trip. These are easy to underestimate and can rival the lift ticket on a destination trip."}],"links":[{"label":"Chatter programs","href":"/programs","internal":true},{"label":"Chatter gear library","href":"/gears/library","internal":true}],"disclaimer":"Every number above is a rough estimate, not a quote, and it''ll shift season to season and resort to resort. Before you plan around any of it, check current prices directly with the resort or shop."}'::jsonb),
  ('budget', 'getting-on-the-mountain-for-less', 1, '{"title":"Budget guide: getting on the mountain for less","description":"Most of the ways people cut the cost of a ski day fall into a handful of categories. None of them require giving up much beyond flexibility — which day you go, which hill you go to, and how far ahead you decide.","paragraphs":["The single biggest lever for most people isn''t a discount code — it''s which mountain and which day. A midweek day at a small local hill and a Saturday at a destination resort can differ by several times over on the ticket alone, before rentals or food enter into it.","Second biggest is planning distance. Nearly every discount structure in the sport rewards deciding early: advance tickets, season passes, multi-day rental rates, and lodging all get more expensive the closer you get to the day.","It''s also worth checking whether you already have access to something. Students, military members, seniors, kids under a certain age, and employees of some large organizations frequently qualify for discounted tickets, and some public libraries and community programs hand out free or reduced passes to local areas.","Chatter Snow runs programs and a gear library aimed squarely at this problem — for some participants they cover the pieces that a discount code can''t."],"list":[{"label":"Ride smaller hills","text":"Local and community-owned areas typically charge a fraction of what destination resorts do, and for learning, less terrain is rarely the limiting factor. Many people spend their first several days somewhere small for this reason."},{"label":"Buy tickets ahead of time","text":"Most resorts price online tickets below the walk-up window, often significantly, and the discount usually gets steeper the earlier you commit. The trade-off is that advance tickets are frequently date-locked and non-refundable."},{"label":"Go midweek or off-peak","text":"Non-holiday weekdays are typically the cheapest days on the calendar, and often the least crowded. Some areas also sell discounted half-day, twilight, or night sessions."},{"label":"Look for beginner packages","text":"Learn-to-ski and learn-to-ride packages bundle a limited ticket, rentals, and a group lesson, and are commonly priced below what those three cost separately. They''re usually limited to beginner terrain."},{"label":"Rent off-mountain","text":"Shops in the nearest town generally price below the resort''s own rental counter, and multi-day rentals typically cost less per day than a series of single days."},{"label":"Bring your own food","text":"On-mountain food is priced like an airport. Packing lunch is an unremarkable and very common way to save $20–$40 a day per person."},{"label":"Split the drive","text":"Carpooling spreads fuel and parking costs, and some resorts reserve their cheapest or most convenient parking for cars arriving with several people in them."}],"links":[{"label":"Chatter programs","href":"/programs","internal":true},{"label":"Chatter gear library","href":"/gears/library","internal":true},{"label":"Learn — Getting Started","href":"/learn/getting-started","internal":true}],"disclaimer":"Pricing, discounts, and eligibility rules all differ by resort and shift every season, so treat the savings above as general patterns, not guarantees. Confirm the actual terms with the resort, shop, or program before counting on them."}'::jsonb),
  ('budget', 'passes-and-deals', 2, '{"title":"Discount passes, deals & off-peak timing","description":"Beyond the day ticket, there''s a whole layer of passes and promotions with different break-even points. Knowing roughly how many days you''ll ride is what makes these comparable — the same pass can be an obvious saving or an expensive mistake depending on that number.","paragraphs":["The useful mental exercise before buying any pass is a rough honest estimate of days: how many did you actually get out last season, and what''s realistically changing this one? Passes are generally sold on optimism, and the break-even math only works if the days materialize.","Watch the fine print as much as the price. Blackout dates around holidays, parking reservations, restrictions to particular terrain, whether a pass covers the whole family or just one person, and whether anything is refundable if the season goes sideways all change what a number is actually worth.","Some passes bundle in extras that shift the comparison — buddy tickets, discounted lodging or rentals, or reciprocal days at other areas. Those can be worth real money, but only if you''d have spent it anyway.","Prices, break-even points, and pass structures shift every season, so the specific comparison is always worth redoing rather than carrying forward from last year."],"list":[{"label":"Season passes","text":"Unlimited or near-unlimited access to one area for a season. Typically cheapest when bought in spring or early fall for the following winter, and the price generally climbs as the season approaches. The break-even against day tickets is often somewhere in the range of five to fifteen days, depending on the area."},{"label":"Multi-resort passes","text":"Products that bundle access to a network of resorts, usually with a set number of days at each or unlimited access at some. Priced for people who travel or ride a lot; rarely the cheapest option for someone riding a handful of local days."},{"label":"Multi-day and punch cards","text":"A block of days bought upfront, typically at a lower per-day rate than singles, often without the commitment of a full season pass. Common at smaller areas."},{"label":"Age-based and status discounts","text":"Many areas price differently for young children, teens, college students, seniors, military members, and ski patrol or industry workers. These are usually the largest single discounts available and often go unclaimed simply because people don''t ask."},{"label":"Off-peak windows","text":"Non-holiday weekdays, early season, and late season are typically the cheapest times to ride. Early and late season come with a real trade-off in conditions and open terrain."},{"label":"Promotions and partner deals","text":"Resorts and their partners run seasonal promotions — retailer bundles, credit card or membership offers, local business tie-ins, opening-weekend rates. These come and go, and are worth a search before buying a ticket at full price."}],"links":[{"label":"Chatter programs","href":"/programs","internal":true}],"disclaimer":"The prices and break-even ranges above are general estimates, not quotes or guarantees — they shift by resort and by season. Read the actual pass terms and confirm current pricing with the resort before you buy."}'::jsonb),
  ('budget', 'renting-vs-buying', 3, '{"title":"Renting vs. buying on a budget","description":"Purely on cost, this comes down to how many days you ride and how long the gear lasts you. The general shape of the trade-off is straightforward, even though the exact numbers depend on your local prices.","paragraphs":["A rough way to think about it: divide what a setup would cost you by a realistic day rental rate, and you get the number of days at which buying starts paying off. For a modestly priced used setup that number is often small; for a new setup at full retail it''s often a season or more of regular riding.","Boots are the usual exception to the whole calculation. They''re the piece most tied to your own feet, rental boots are the most commonly cited source of a miserable first day, and many people buy boots well before they buy skis or a board for that reason rather than a financial one.","There''s a non-financial side too: owning means transporting, storing, drying, and maintaining gear, and eventually paying for tunes or repairs. Renting bundles all of that into the daily rate. If storage or a car is tight, renting can be the cheaper option in practice even when the math says otherwise.","If you''re leaning toward buying, sizing matters more than price — gear that doesn''t fit is a bad deal at any discount. A shop fitter can confirm what sizes make sense for you before you start shopping, and Chatter Snow''s gear library is another way to get on equipment without buying it."],"list":[{"label":"Renting","text":"No upfront cost, no storage, no maintenance, and you''re on reasonably current, shop-tuned equipment. Typically somewhere around $40–$70 a day for a full package at a resort, often less off-mountain or on a multi-day rate."},{"label":"Season rentals","text":"Many shops rent a package for the whole winter for roughly what a handful of day rentals would cost. A common middle step for people riding more than a few days but not ready to buy — and frequently offered for kids, who outgrow gear yearly."},{"label":"Demo programs","text":"Shops that rent higher-end equipment, sometimes crediting part of the demo fee toward a purchase. Costs more per day than a basic rental, and is mainly useful for trying specific gear before buying."},{"label":"Buying new","text":"The largest upfront cost and the lowest per-day cost over time, if you ride enough. It also means boots that are actually yours, which is the part most people notice first."},{"label":"Buying used","text":"Much lower upfront cost, with more responsibility on you to judge condition. Covered in the next article."}],"links":[{"label":"Chatter gear library","href":"/gears/library","internal":true},{"label":"Gear sizing guides","href":"/gears/sizing","internal":true},{"label":"Learn — Gear Care","href":"/learn/gear-care","internal":true}],"disclaimer":"The rental rates and break-even math here are ballpark, not quotes — they vary by region and shop. For sizing and fit, a shop fitter or certified technician will get you a better answer than an article will."}'::jsonb),
  ('budget', 'used-gear', 4, '{"title":"Finding used gear without overpaying","description":"The used market is where most of the real savings in this sport live, and it''s also where it''s easiest to buy something that doesn''t work out. This is an overview of where people look and what tends to matter — not an appraisal guide.","paragraphs":["The general condition checks people apply: look at the base for deep gouges that reach the core, the edges for rust, cracks, or how much material is left after repeated tunes, and the topsheet and sidewall for delamination. On a snowboard or skis, bindings that shift under hand pressure or mounting holes that look reworked are worth asking about.","For boots, condition matters less than fit, and fit is individual — a great price on the wrong shell shape is money spent on a bad day. Trying boots on, ideally with help from a shop fitter, is the part that''s hard to shortcut on the used market.","One thing that isn''t a bargaining detail: used ski bindings need to be inspected and adjusted by a certified technician before they''re used, and some bindings are old enough that shops won''t work on them at all. Ask a shop whether a specific model is still serviceable before buying, and never set or adjust a DIN yourself — a certified technician does that.","On price, the useful anchor is what the same item sells for new and what similar used listings ask. Gear that''s been sitting for a decade, is missing parts, or shows structural damage is generally cheap for a reason, and getting it into usable shape can cost more than the discount saved."],"list":[{"label":"Ski swaps","text":"Seasonal sales run by clubs, schools, patrols, and shops, usually in fall. Typically the highest concentration of used gear in one place, often with knowledgeable people around to ask."},{"label":"Shop end-of-season sales","text":"Shops clear out rental fleets and last year''s stock in spring. Rental gear has had a hard life but is usually maintained and honestly described."},{"label":"Online marketplaces","text":"The widest selection and the widest range of quality. Photos hide a lot, so this is where inspecting in person before paying matters most."},{"label":"Gear libraries and community programs","text":"Some nonprofits and community organizations lend equipment rather than selling it — worth checking locally before buying anything."},{"label":"Last season''s new gear","text":"Not used at all, just outdated by a model year. Often discounted meaningfully once the new lineup lands, with none of the condition uncertainty."}],"links":[{"label":"Chatter gear library","href":"/gears/library","internal":true},{"label":"Gear sizing guides","href":"/gears/sizing","internal":true},{"label":"Learn — Gear Care","href":"/learn/gear-care","internal":true}],"disclaimer":"Consider this a map of the used market, not an inspection or an appraisal. Prices here are rough estimates that vary a lot, and for the condition and safety of used gear — bindings especially — a shop or certified technician''s actual assessment is what counts, not this page."}'::jsonb),
  ('etiquette', 'basics', 0, '{"title":"Mountain & lift etiquette basics","description":"Most of what keeps a busy mountain running smoothly isn''t posted anywhere — it''s a set of habits everyone out there is quietly relying on each other to follow. This is an overview of the common ones, not any particular resort''s rulebook.","paragraphs":["Etiquette on a mountain mostly comes down to one idea: the person below or ahead of you can''t see you, so the responsibility for avoiding them sits with you. Nearly every specific convention — where to stop, when to yield, how to pass — is some version of that.","Speed is the other half of it. What counts as reasonable depends on how crowded the trail is, how well you can see ahead, and the conditions that day, which is why slow zones near lift lines, trail merges, and learning areas are marked out separately.","Ski patrol handles injuries, closures, and unsafe riding, and they''re also generally the people to flag down if you come across an incident or something that looks wrong on the hill. Most resorts post how to reach them, and lift attendants can radio them.","Resorts each have their own posted rules on top of the general norms — uphill travel policies, drone rules, leashes, and where personal cameras or speakers are welcome vary quite a bit. Checking a mountain''s website or the signage at the base area is the reliable way to know."],"list":[{"label":"Stay predictable","text":"Other people are reading your line and planning around it. Sudden stops, sharp cuts across a trail, and unannounced direction changes are what tend to catch riders behind you off guard."},{"label":"Stop where you can be seen","text":"The usual habit is to pull over to the side of a trail and out of blind spots — below a roller, just past a lip, or around a bend is where an uphill rider has the least time to react."},{"label":"Look uphill before you go","text":"Merging onto a trail or starting again after a break generally means yielding to whoever''s already coming down."},{"label":"Pack out what you bring","text":"Wrappers and cans dropped from a lift end up in the snow under it. Most base areas and lift lines have bins, and many resorts ask you to carry trash down rather than leave it on the hill."},{"label":"Respect closures and boundaries","text":"Ropes, fencing, and closure signs generally mean grooming, avalanche work, thin cover, or an incident in progress — reasons that usually aren''t visible from where you''re standing."},{"label":"Give beginners room","text":"Learning areas and slow zones exist because people fall there. Passing wide and at a lower speed is the norm through them."}],"links":[{"label":"NSAA — Your Responsibility Code","href":"https://www.nsaa.org/NSAA/Safety/Your_Responsibility_Code.aspx"},{"label":"Chatter Snow events & mountain days","href":"/events","internal":true}],"disclaimer":"These are widely shared norms, not any one mountain''s official rulebook — posted signage, the resort''s own site, and ski patrol are the actual authority on how a place expects people to ride."}'::jsonb),
  ('etiquette', 'lift-lines', 1, '{"title":"Lift line etiquette","description":"The lift line is where the most people are packed into the smallest space, so it''s where etiquette gets noticed the fastest. Here''s how lines usually work and what''s generally expected while you''re in one.","paragraphs":["On the chair itself, the bar convention varies by region and by resort — some mountains require it, some leave it to the riders. Asking or giving a heads-up before lowering or raising it is the usual courtesy, since it catches people off guard otherwise.","If something goes wrong at loading or unloading — a fall, dropped equipment, a stuck rider — lift attendants can slow or stop the lift, and that''s what the stop is there for. Trying to sort it out yourself while the chairs keep moving is generally how a small problem becomes a bigger one.","Lines are also where a lot of first-timers feel most out of place. Attendants deal with new riders constantly and are used to being asked which line is which, whether a lift is beginner-friendly, and how to load — asking is normal, not an imposition.","Practices differ between resorts and lift types, and gondolas, surface lifts, and magic carpets each have their own loading routine. Posted instructions at the base of the lift are the thing to go by."],"list":[{"label":"Merge, don''t cut","text":"Lines typically funnel through a maze and alternate as they merge. Slotting in beside someone who''s been waiting is the thing most likely to get a reaction."},{"label":"Fill the chair","text":"Attendants often ask singles to pair up so chairs go out full, especially when the line is long. The singles line exists for exactly this."},{"label":"Sort out your group first","text":"Deciding who''s riding with whom before you reach the loading point keeps the line moving; sorting it out at the gate tends to stop everyone behind you."},{"label":"Get your pass ready","text":"Scanners usually read a pass in a pocket or on a sleeve, but only if it''s not buried under a layer you have to unzip at the gate."},{"label":"Mind your equipment","text":"Skis and boards in a line have edges. Keeping them flat, out from underfoot, and off the backs of the people ahead is the general courtesy."},{"label":"Load and unload smoothly","text":"Watch the chair, sit as it comes, and once you''re off at the top, keep moving clear of the unload ramp rather than stopping to adjust gear there."}],"links":[{"label":"NSAA — Your Responsibility Code","href":"https://www.nsaa.org/NSAA/Safety/Your_Responsibility_Code.aspx"},{"label":"Chatter Snow events & mountain days","href":"/events","internal":true}],"disclaimer":"Lift procedures shift by resort and by lift, so follow the posted instructions and the attendants at your actual mountain — not a general description like this one."}'::jsonb),
  ('etiquette', 'right-of-way', 2, '{"title":"Sharing the trail: right-of-way basics","description":"Trails have no lanes and no signals, so who yields to whom is settled by a handful of conventions everyone is expected to know. This explains what those conventions are and the thinking behind them.","paragraphs":["Right of way on snow works differently than on a road because everyone''s field of view points downhill. The rider above sees everything ahead of them; the rider below sees none of what''s coming. Assigning the responsibility uphill is simply where it can actually be acted on.","Speed control belongs to the same idea. Being able to stop or turn within the distance you can see is what makes yielding possible at all, and it''s why crowded runs, flat light, and narrow cat tracks call for a lot more margin than an empty groomer does.","Collisions between riders are one of the more common ways people get hurt on a mountain, and they tend to happen at merges, on crowded runs at the end of the day, and in the flat spots where people stop to regroup. If you''re involved in one, stopping and exchanging information is expected the same way it would be after a car accident, and ski patrol should be involved if anyone is hurt.","If someone is injured, get ski patrol rather than trying to assess or move them yourself — they''re trained and equipped for on-mountain injuries. Planting crossed skis or a board upslope of the scene is a widely used signal to alert riders coming down."],"list":[{"label":"The person ahead has right of way","text":"Whoever is downhill or in front of you generally can''t see you coming, so avoiding them is on you — this is the foundation the rest of it sits on."},{"label":"Announce a close pass","text":"A simple \"on your left\" or \"on your right\" when you''re passing tight is the common courtesy, though leaving enough room that it isn''t needed is better still."},{"label":"Merging means yielding","text":"Where trails join, riders coming onto the trail typically look uphill and wait for a gap rather than the through traffic slowing for them."},{"label":"Starting again is merging","text":"Getting up after a fall or a break puts you back into traffic, so the same look-uphill habit applies."},{"label":"Don''t stop in a blind spot","text":"Just past a rise, under a lip, or around a corner leaves an uphill rider no time to react. Pulling to the edge with clear sightlines above you is the norm."},{"label":"Watch for the mountain''s other traffic","text":"Snowmobiles, grooming machines, patrol sleds, uphill skinners, and lift maintenance all share the terrain, sometimes outside normal hours."}],"links":[{"label":"NSAA — Your Responsibility Code","href":"https://www.nsaa.org/NSAA/Safety/Your_Responsibility_Code.aspx"},{"label":"Park riding & safety — terrain park etiquette","href":"/learn/park-riding-safety","internal":true}],"disclaimer":"This is orientation to how riders share terrain, not safety training or medical guidance. If an injury''s involved, that''s ski patrol or a medical professional — and whatever your resort has posted always beats a general description like this."}'::jsonb),
  ('etiquette', 'responsibility-code', 3, '{"title":"Uphill/downhill traffic & the Responsibility Code","description":"Most of the etiquette on this page traces back to a published code of conduct posted at resorts across North America, plus a separate set of expectations for anyone traveling uphill. This covers what those are and where to read them.","paragraphs":["The Responsibility Code isn''t a law in most places, but it''s the reference point resorts, ski patrol, and instructors generally use when describing what''s expected, and some states and resorts do tie their own rules to it. It''s worth reading in full once — it''s about seven short lines.","Uphill access policies vary far more than downhill etiquette does. Some resorts welcome uphill travel on marked routes during set hours, some require a specific pass or an orientation, and some prohibit it entirely, including outside operating hours. The policy is normally published on the resort''s website and posted at the base area.","Uphill travel outside a resort''s operating hours generally means no patrol coverage, no lift evacuation, and machinery on the hill, which is why the policies are as specific as they are. Anyone considering it is best served reading the mountain''s own policy first and asking guest services or patrol about anything unclear.","Terrain outside a resort''s boundary is a different matter again — that''s backcountry, with avalanche risk, no patrol, and its own training and equipment expectations that go well beyond etiquette."],"list":[{"label":"Your Responsibility Code","text":"A short list of shared expectations — control your speed, yield to those ahead of and below you, look uphill before merging or starting, observe signs and closures — published by the National Ski Areas Association and posted at most resorts."},{"label":"Downhill traffic","text":"The general rule for riders coming down: the person below or ahead of you has the right of way, and staying in control enough to avoid them is what makes that workable."},{"label":"Uphill traffic","text":"Skinning, splitboarding, or hiking up a resort''s terrain is governed by that resort''s own uphill policy, which typically sets designated routes, permitted hours, and whether a pass is required."},{"label":"Stay to the edge going up","text":"Where uphill travel is allowed, the usual expectation is single file at the side of the trail, out of the fall line and visible to riders coming down."},{"label":"Grooming and snowmaking hours","text":"Winch cats run cables across trails and snow guns run overnight, which is a large part of why uphill hours are restricted at all."}],"links":[{"label":"NSAA — Your Responsibility Code","href":"https://www.nsaa.org/NSAA/Safety/Your_Responsibility_Code.aspx"},{"label":"Park riding & safety — terrain park etiquette","href":"/learn/park-riding-safety","internal":true}],"disclaimer":"This is a summary, not the code itself and not legal advice — read the published code directly, and check the uphill and access policy at whichever resort you''re actually visiting, since those differ mountain to mountain."}'::jsonb),
  ('park-riding-safety', 'etiquette', 0, '{"title":"Terrain park etiquette & responsibility code","description":"Terrain parks carry the same responsibility code as the rest of the mountain, plus a few extra norms specific to features, takeoffs, and landings. This is the general shape of it — always confirm a resort''s own park rules with posted signage or ski patrol.","paragraphs":["Right-of-way in the park generally goes to whoever''s already committed to a feature or still in the landing zone — wait your turn rather than dropping in on top of someone.","Call your drop-in when other riders are around so people know to clear the landing, and move out of the way quickly once you''re down so the next person has room.","Treat posted closures, ropes, and signage as off-limits even if a feature looks ridable — closures usually mean grooming, feature maintenance, or an incident in progress."],"list":[{"label":"Start small","text":"Get comfortable on smaller, slower features before working up to anything bigger, faster, or more technical."},{"label":"Plan your line","text":"Decide your speed and path before you commit to a feature, not while you''re already on it."},{"label":"Look before you drop","text":"Confirm the feature and landing are clear, and that the rider ahead of you has cleared out, before you go."},{"label":"Respect the feature and others","text":"Don''t stop or linger in a landing zone, blind spot, or takeoff, and give the next rider room to land and clear."},{"label":"Know your limits","text":"It''s fine to walk a feature or session something smaller — there''s no prize for pushing past what you''re ready for."}],"links":[{"label":"NSAA — Your Responsibility Code","href":"https://www.nsaa.org/NSAA/Safety/Your_Responsibility_Code.aspx"},{"label":"NSAA — Park Smart terrain park safety","href":"https://skisafety.us/terrain-park-safety"}],"disclaimer":"These are general norms, not any one mountain''s official rulebook — check posted signage or ask ski patrol how your resort actually runs its park."}'::jsonb),
  ('park-riding-safety', 'progression', 1, '{"title":"Park feature progression basics","description":"Terrain parks group features into a few broad categories, usually graded by size the same way trails are graded by difficulty. This is an overview of what''s out there, not instruction on how to ride any of it.","paragraphs":["Progression in the park usually means starting on the smallest size in a category and getting genuinely comfortable there, not just surviving it once, before moving up a tier.","A big share of terrain-park injuries come from attempting something a rider isn''t ready for yet, rather than from the features themselves. Skipping a size tier because a bigger feature \"looks doable\" is one of the more common ways that happens.","For actual technique and how to build toward a specific feature, a lesson or instructor is the right resource — ski patrol is also there if you''re ever unsure whether something is within your current ability."],"list":[{"label":"Rails & boxes","text":"Narrow metal or plastic features you slide across. Usually the entry point into park riding, and typically graded small, medium, or large by height and length."},{"label":"Jumps","text":"Shaped mounds of snow with a takeoff, a gap, and a landing. Resorts typically group jumps into small, medium, and large lines by how much air time and distance they cover."},{"label":"Halfpipe","text":"A U-shaped trench with two opposing walls. Fewer resorts maintain one, and it''s generally considered advanced terrain."}],"links":[{"label":"Chatter programs — mentorship & beginner sessions","href":"/programs","internal":true},{"label":"NSAA — Park Smart terrain park safety","href":"https://skisafety.us/terrain-park-safety"}],"disclaimer":"This is a rundown of feature types, not a how-to. For actual technique and safely working up to a specific feature, an instructor or experienced rider will teach you more than an article ever could."}'::jsonb),
  ('park-riding-safety', 'safety-gear', 2, '{"title":"Park safety gear & injury-prevention awareness","description":"Terrain parks carry more fall and collision risk than groomed runs, so a few things matter more here than they might elsewhere on the mountain.","paragraphs":["Before dropping into a feature, take a moment to check that the landing and run-out are clear, wait for the rider ahead of you to fully clear the area, and know where you''re headed once you''re down.","If you or someone nearby is hurt, get ski patrol involved — most resorts have a way to flag them down, and features are usually marked with the nearest contact point or call box. Ski patrol is trained for on-mountain injuries in a way a fellow rider isn''t.","And to be clear, none of this is medical guidance — don''t try to diagnose or treat an injury beyond whatever first aid you''re actually trained in. Get the person to ski patrol or another qualified professional and let them take it from there."],"list":[{"label":"Helmet","text":"A properly fitted helmet is close to standard in terrain parks at this point — most resorts strongly encourage or require one in park zones."},{"label":"Wrist guards","text":"Common for snowboarders, especially while learning — wrists are one of the most frequently injured areas in falls."},{"label":"Padding","text":"Impact shorts, knee pads, or a back protector are worth considering for park riding, where falls tend to be harder and less predictable than on groomed terrain."}],"links":[{"label":"NSAA — Park Smart terrain park safety","href":"https://skisafety.us/terrain-park-safety"}],"disclaimer":"This is general awareness, not medical or first-aid training — if there''s an actual injury involved, that''s ski patrol or a medical professional, not this article."}'::jsonb),
  ('gear-care', 'between-trips', 0, '{"title":"Gear care 101: between-trip basics","description":"Most of what keeps snow gear working is unglamorous — drying things out and putting them away properly. Here''s the general shape of what people do between trips, and why each piece of it matters.","paragraphs":["The short version of between-trip care is: get it dry, get the water off the metal, and store it somewhere stable. Almost everything else is refinement on top of those three things.","Outerwear generally benefits from being washed less often than everyday clothes but not never — most technical fabrics have manufacturer care instructions on the tag, and following the instructions for the specific garment is more reliable than any general rule an article can offer.","If something looks structurally wrong — a binding that shifts under hand pressure, a boot shell with a crack in it, a base gouge deep enough to show the core — that''s shop territory rather than a between-trip fix. A shop tech can tell you whether it''s cosmetic or worth repairing."],"list":[{"label":"Dry everything","text":"Boot liners, gloves, and base layers hold a surprising amount of moisture after a day out. Air-drying them at room temperature is the usual approach; direct heat from a radiator, wood stove, or car heater can warp or crack liners and shell plastics over time."},{"label":"Wipe down edges","text":"Skis and boards come off the mountain wet, and steel edges rust. Drying the bases and edges with a towel before the gear goes in a bag is the common habit that heads that off."},{"label":"Loosen buckles and straps","text":"Boots are typically stored buckled loosely rather than cranked down or fully open, so the shell keeps its shape without being held under tension."},{"label":"Don''t leave gear in the car","text":"A cold trunk is a wet, temperature-swinging place to store equipment, and gear left there tends to stay damp between trips rather than drying out."},{"label":"Look things over","text":"A quick check for loose screws, cracked buckles, delaminating base material, or a torn jacket seam is easier to act on now than the morning of the next trip."}],"links":[{"label":"Chatter gear library","href":"/gears/library","internal":true}],"disclaimer":"These are general habits, not manufacturer instructions — care requirements vary by product, so whatever''s on the care tag or manual for your specific gear wins over anything written here."}'::jsonb),
  ('gear-care', 'waxing', 1, '{"title":"Waxing & base care explained","description":"Wax is a consumable: it wears off as you ride and gets reapplied. This explains what waxing does and the general options for getting it done, rather than walking through a tuning-bench procedure.","paragraphs":["Shops sell waxing as part of a tune, usually bundled with a base grind or edge work. As a rough sense of scale, a basic wax is typically among the cheaper shop services and a full tune costs more; actual prices vary a lot by region and shop, so treat any number you see online as an estimate and ask locally for a real one.","Home waxing is common enough that irons, scrapers, and brushes are widely sold, but it involves a hot iron, a solid work surface, and some practice to avoid overheating the base. If you want to learn it, having someone show you in person — a shop tech, a tuning clinic, or an experienced friend — is the usual way people pick it up.","Some bases and some gear aren''t good candidates for a home iron at all, including rental equipment you don''t own and boards with graphics or sintered bases you''d rather not risk. When in doubt, a shop is the low-risk option."],"list":[{"label":"What wax does","text":"The base of a ski or board is a porous plastic that absorbs wax. Wax reduces friction against the snow and helps keep the base from drying out, which is why an unwaxed base can feel slow and look chalky or white-ish, especially along the edges."},{"label":"Hot wax","text":"Wax melted onto the base with an iron, allowed to cool, then scraped and brushed off. It''s the standard shop approach and generally lasts longer than the alternatives."},{"label":"Rub-on and paste wax","text":"Applied cold without an iron. Quicker and less involved, but typically wears off faster — often thought of as a top-up between real waxes rather than a replacement."},{"label":"Temperature-specific wax","text":"Waxes are commonly sold graded by snow temperature range, plus all-temperature blends. The graded ones matter most to racers; recreational riders often just use an all-temp wax."},{"label":"Frequency","text":"How often gear needs wax depends on how much you ride, the snow conditions, and how picky you are. Some people wax every handful of days out; others go a season. There''s no single correct interval."}],"links":[{"label":"Chatter gear library","href":"/gears/library","internal":true}],"disclaimer":"This explains what waxing is, not how to do it — hot waxing involves heat and equipment that can damage a base, so a shop tech or someone showing you in person is the right place to actually start."}'::jsonb),
  ('gear-care', 'edge-tuning', 2, '{"title":"Edge tuning: what it is and when to see a shop","description":"Edge tuning is shaping and sharpening the steel edges of a ski or board. It affects how the gear grips and releases, and it''s a job most people hand to a shop — this covers what the terms mean so the conversation at the counter makes sense.","paragraphs":["Edge angles are specific to the equipment and to the rider — the right setup depends on the gear''s design spec, the conditions you ride, your ability, and your discipline. That combination is a judgment call for a shop technician who can look at your actual gear, not something to pick from a chart or an article. This is the same reasoning behind leaving binding release (DIN) settings to a certified binding technician.","Signs that commonly send people to the shop include an edge that catches or feels grabby, visible nicks or rust along the steel, a base gouge, or gear that slips on firm snow when it used to hold. A shop can tell you whether it needs a tune, a repair, or nothing at all.","Getting a tune before the season starts and after any hard rock hit is a common rhythm. Shops are typically busiest right at the start of the season and around holidays, so turnaround times tend to be longer then."],"list":[{"label":"Base edge and side edge","text":"Edges are filed on two faces — the one along the base and the one along the sidewall — each set to a small angle. Those angles are what a tune actually adjusts."},{"label":"Bevel","text":"The angle each edge face is filed to, measured in degrees. Different combinations trade off grip on hard snow against how forgiving the gear feels, and manufacturers publish a factory spec for their own equipment."},{"label":"Detuning","text":"Deliberately dulling short stretches of edge, often near the tip and tail or along a board''s contact points, so the edge is less likely to catch. Common for park riding and for beginners."},{"label":"Burrs","text":"Small rough spots raised in the steel by rocks or rails. They''re what makes an edge feel grabby or snag, and removing them is a routine part of a tune."},{"label":"Base grind","text":"Machine-resurfacing the base to make it flat again and cut a texture into it. It''s a bigger service than a wax or an edge tune and is done on shop machinery."}],"links":[{"label":"Ski sizing & binding DIN reference","href":"/gears/sizing","internal":true}],"disclaimer":"This is here so the terminology makes sense at the counter, not a how-to for tuning your own edges — and it''s not a recommendation on any particular bevel. Edge angles and binding settings are a qualified shop tech''s call, working with your actual gear."}'::jsonb),
  ('gear-care', 'off-season-storage', 3, '{"title":"Off-season storage basics","description":"Gear spends more of the year in storage than on snow, and how it''s stored is a common reason equipment comes out of the closet in worse shape than it went in.","paragraphs":["The end of the season is also a natural time to deal with anything you noticed but rode through — a torn seam, a stripped screw, a base gouge. Shops are usually quieter in spring and summer than in the fall rush.","Batteries are worth pulling out of anything that has them — heated gloves, avalanche transceivers, boot heaters — since batteries left in storage can leak and corrode contacts.","If you''re storing borrowed or program gear rather than your own, follow whatever the lending program asks for; those requirements exist so the next person gets equipment in usable shape."],"list":[{"label":"Store it dry","text":"Everything goes away fully dry — boots, liners, gloves, outerwear, and bases. Damp gear in a sealed bag is how mildew and rusted edges happen over a summer."},{"label":"Somewhere stable","text":"A cool, dry, temperature-stable indoor space is the usual recommendation. Unconditioned attics, garages, and sheds swing hard between hot and cold, and sustained heat is hard on plastics, glues, and base material."},{"label":"Storage wax","text":"A thick coat of wax left unscraped over the base and edges is the common way people protect gear over the summer. It''s scraped off before the first day back on snow."},{"label":"Release binding tension","text":"Backing off ski binding spring tension for the off-season is a frequently suggested practice. Because it changes the release setting, it''s worth having the shop do it — and having them reset and test it before you ride again."},{"label":"Out of direct sun","text":"UV is hard on topsheets, straps, and outerwear fabric. Storing gear out of sunlight is a small thing that adds up over years."},{"label":"Boots keep their shape","text":"Boots are typically stored buckled loosely with the liners in and dry, rather than crushed under other gear or left unbuckled to splay open."}],"links":[{"label":"Chatter gear library","href":"/gears/library","internal":true}],"disclaimer":"These are general storage habits, nothing more. Binding tension or release settings are a certified binding technician''s job to handle and re-test, and your gear''s own manufacturer storage instructions beat anything written here."}'::jsonb),
  ('gear-care', 'when-to-replace', 4, '{"title":"Knowing when gear needs replacing","description":"Snow gear doesn''t all wear out on the same schedule, and some of it fails in ways you can''t see. This is a general sense of what to watch for and who to ask — not a verdict on any particular piece of your equipment.","paragraphs":["For anything protective — helmets and avalanche gear especially — the manufacturer''s own guidance for that specific model is the authority, and a shop can help you find it. Erring toward replacement is the common posture with safety equipment precisely because the failure mode isn''t visible.","Age alone isn''t automatically disqualifying for skis, boards, and outerwear; condition and how it''s been stored matter more. A shop tech looking at the actual gear can tell you far more than a rule of thumb can.","If cost is what''s standing between you and replacing something that''s genuinely worn out, gear libraries, swaps, and community programs exist for that. Chatter''s gear library is one option, and many local shops and clubs run season-opening swaps."],"list":[{"label":"Helmets","text":"Helmets are generally treated as single-impact items: after a significant crash, the protective foam may be compromised even with no visible damage. Manufacturers also publish a recommended replacement interval regardless of impacts, commonly measured in a handful of years."},{"label":"Bindings","text":"Manufacturers and shops maintain indemnified lists of bindings they''ll still test and service. Once a binding drops off that list, shops typically won''t work on it, which in practice is the end of its usable life."},{"label":"Boots","text":"Boots wear out from the inside — liners pack out and lose volume, and shells eventually lose stiffness. Cracked shells and worn-through sole blocks are the visible versions; a boot fitter can tell you whether a boot has more life in it or needs replacing."},{"label":"Skis and boards","text":"Bases can only be ground so many times before there isn''t enough material left, edges can only be filed so far, and delamination or a soft, dead feel underfoot are signs the construction is going. None of these have a fixed mileage."},{"label":"Outerwear","text":"Jackets and pants usually fail gradually — the water-repellent finish wears off first and can often be renewed, while worn-through fabric, failed taped seams, and broken zippers are the point where repair or replacement is the question."},{"label":"Avalanche safety equipment","text":"Transceivers, airbags, and similar equipment have their own manufacturer service life, firmware, and inspection requirements. Follow the manufacturer''s guidance for the specific device rather than any general rule."}],"links":[{"label":"Chatter gear library","href":"/gears/library","internal":true}],"disclaimer":"This is general awareness, not an assessment of your actual equipment — whether a specific helmet, binding, or piece of avalanche gear is still safe to use is a question for the manufacturer''s guidance and a qualified shop technician, not this page."}'::jsonb),
  ('community-and-inclusion', 'finding-your-place', 0, '{"title":"Finding your place in the snow sports community","description":"Snow sports can look like a closed circle from the outside — full of people who grew up doing it and already know each other. It isn''t one, but finding a way in is easier when you know where people actually connect.","paragraphs":["The sport carries a real history of being expensive and exclusive, and it''s fair to notice that. What''s also true is that a lot of organizations now exist specifically to widen who gets to participate, and most of them are actively looking for newcomers rather than waiting to be impressed by them.","Community is usually built through repetition rather than a single introduction. Showing up to the same group day, clinic, or volunteer shift a few times generally does more than any one perfect first outing.","You do not have to be good at this to belong in it. Most people on any given mountain are somewhere in the middle of their own learning, and the ones who have been at it longest have generally forgotten how quickly the early stages pass.","If a particular group or space doesn''t feel like a fit, that''s information about that group, not about whether snow sports are for you. There are usually several communities around a single mountain, and they differ a lot in tone."],"list":[{"label":"Community programs & nonprofits","text":"Organizations built specifically to get new people on the mountain — beginner sessions, gear lending, group trips. They generally assume you''re starting from zero, which is the whole point of them."},{"label":"Clubs & meetup groups","text":"Regional ski and snowboard clubs typically organize carpools, group days, and season trips. Many run separate beginner-friendly days, and it''s reasonable to ask before signing up which of theirs those are."},{"label":"Affinity groups","text":"Groups organized around shared identity or background — among many others, riders of color, LGBTQ+ riders, women''s collectives, and adaptive sports organizations. They exist because showing up somewhere you''re not the only one changes the experience for a lot of people."},{"label":"Lessons & clinics","text":"A group lesson or a multi-week clinic puts you with other people at the same stage. The shared-progress part is a common way people end up with regular riding partners."},{"label":"Adaptive programs","text":"Adaptive snow sports organizations work with riders with disabilities, using specialized equipment and trained instructors. Availability varies by resort and region, so their own intake process is the place to start."},{"label":"Volunteering","text":"Gear sorting, event help, and program support are ways into a community that don''t require riding well — or riding at all — and they tend to put you around people who ride."}],"links":[{"label":"Chatter programs — mentorship & beginner sessions","href":"/programs","internal":true},{"label":"Community events","href":"/events/community","internal":true},{"label":"Get involved & volunteer","href":"/get-involved","internal":true}],"disclaimer":"This describes the kinds of groups and programs out there in general terms, not an endorsement of any specific one. What''s actually near you, who it serves, and how to join all vary by region — check with the organization directly."}'::jsonb),
  ('community-and-inclusion', 'beginner-buddy-guide', 1, '{"title":"Beginner buddy guide: riding with a mentor","description":"Plenty of first-timers learn alongside someone more experienced. That works well when both people are clear on what the day is for — and goes sideways when they aren''t.","paragraphs":["If you''re the mentor, most of the value you''re adding is logistical and social rather than technical: where to park, how the rental shop works, what the lift is going to ask of you, and what the signs mean. That''s genuinely useful, and it doesn''t require you to teach technique you aren''t qualified to teach.","If you''re the beginner, it''s worth saying at the start what you actually want out of the day. \"I want to get comfortable on the learning area and ride one lift\" is a clearer target than \"I want to try skiing,\" and it gives your mentor something concrete to work with.","A common pattern is a lesson first and a mentor after — the lesson covers the technique, and the mentor covers the everything-else of a normal day. Neither replaces the other especially well.","Both people should know that ski patrol handles anything that goes wrong on the mountain, and that patrol is called rather than worked around. If someone is hurt, the answer is patrol and medical attention, not a friend''s assessment of how bad it looks.","Mentorship also works as a formal arrangement. Programs that pair newer riders with experienced volunteers — ours among them — exist partly because not everyone has a friend who already rides."],"list":[{"label":"A mentor isn''t an instructor","text":"Riding well and being trained to teach are different things. A mentor can show you how a day works, where things are, and what the vocabulary means; certified instruction is a separate role and a separate qualification."},{"label":"Agree on the day before you get there","text":"How long you''ll ride, what terrain you''ll stay on, and when you''ll stop are much easier to settle in the parking lot than partway down something you didn''t expect."},{"label":"The beginner sets the pace","text":"The person with less experience is the one who knows when they''re tired, cold, or done. A mentor''s job is generally to make that easy to say out loud rather than something that has to be admitted."},{"label":"Terrain stays where the beginner is","text":"Being taken onto a run beyond your comfort is the most common way a mentor day goes badly. \"You''ll be fine\" is not a terrain assessment, and it''s reasonable to decline a run for any reason or no reason."},{"label":"Agree on a meeting plan","text":"Where to regroup, what happens if you get separated, and whether phones will actually work up there. Simple, decided in advance, and known by both people."},{"label":"Falling is expected","text":"It''s a normal part of the early stages, not evidence the day is going wrong. A useful mentor treats it that way."}],"links":[{"label":"Chatter programs — mentorship & beginner sessions","href":"/programs","internal":true},{"label":"NSAA — Your Responsibility Code","href":"https://www.nsaa.org/NSAA/Safety/Your_Responsibility_Code.aspx"},{"label":"Volunteer with Chatter Snow","href":"/get-involved/volunteer","internal":true}],"disclaimer":"A friend riding with you is not a substitute for a certified instructor, and nothing here is technique guidance. If anyone gets hurt, that''s ski patrol and medical attention, not a mentor''s call."}'::jsonb),
  ('community-and-inclusion', 'mixed-skill-levels', 2, '{"title":"Riding with mixed skill levels in your group","description":"Groups rarely arrive at the same ability. A day works better when that''s planned around rather than discovered on the first chairlift.","paragraphs":["The recurring failure mode in mixed groups isn''t skill, it''s pace. A slower rider on their own terrain generally has a good day; the same rider trying to keep up with people on harder runs generally doesn''t.","Trail ratings are relative to a single resort, so \"it''s just a blue\" means less than it sounds like, especially between mountains. Reading the trail map together at the start of the day gives everyone the same picture of what''s actually on offer.","If your group includes someone on their first day, they''re often the person least likely to say they''re uncomfortable. Checking in directly, and making \"let''s stop\" a normal thing to hear, tends to work better than waiting for them to raise it.","The responsibility code applies to everyone in the group individually — including responsibility for the people ahead of you on a trail and for stopping somewhere you can be seen. It''s worth everyone having read it once, not just the newest rider.","Groups that regularly ride together across levels usually end up with some version of this as a habit rather than a conversation. Setting it up on the first day just gets you there sooner."],"list":[{"label":"Split and regroup","text":"A common approach is riding separately by ability and meeting at set times and places — the base lodge at lunch, or the bottom of a shared lift each hour. Everyone gets the day they came for."},{"label":"Pick a shared home base","text":"One lift or one area that everyone can get back to, whatever they''ve been riding. It makes regrouping a location rather than a negotiation."},{"label":"Don''t route by the strongest rider","text":"If terrain choice follows whoever rides best, the least experienced person in the group ends up somewhere they didn''t choose. Routing by the person with the least experience is the version that keeps the group together."},{"label":"Say what you want from the day","text":"People in the same group often want different things — laps, sightseeing, a break in the lodge, or just to make it down once. None of those are wrong, and they''re easier to accommodate when stated."},{"label":"Agree on when to stop","text":"Fatigue is uneven across a group, and later runs are where tired people tend to get hurt. Deciding in advance that anyone can call it done removes the pressure to keep up."},{"label":"Have a plan for getting separated","text":"Cell service is unreliable at many resorts. A fallback meeting point and time is worth more than an assumption that you can text."}],"links":[{"label":"NSAA — Your Responsibility Code","href":"https://www.nsaa.org/NSAA/Safety/Your_Responsibility_Code.aspx"},{"label":"Chatter Snow events & mountain days","href":"/events","internal":true}],"disclaimer":"This is about organizing a group day, not a judgment on what terrain is right for any one person. A certified instructor is who actually assesses ability and terrain, and ski patrol handles anything that goes wrong on the mountain."}'::jsonb),
  ('community-and-inclusion', 'first-timer-intimidation', 3, '{"title":"Overcoming first-timer intimidation","description":"Feeling out of place on a first day is extremely common, and it''s usually about the unfamiliar logistics as much as the sport itself. Naming what''s actually intimidating tends to shrink it.","paragraphs":["A lot of first-day anxiety is really about not knowing the sequence of a day — where to go, in what order, and what you''ll be asked. Reading through what a first day looks like beforehand takes most of the unknown out of it, which is a large part of what the Getting Started articles are for.","Going with someone else helps for most people, whether that''s a friend, a group lesson, or a community beginner session. A group lesson in particular puts you with several other people who are also there for the first time.","Progress in the early stages is uneven and person-specific. Measuring your first day against someone else''s — especially someone who started as a kid — is a comparison with no useful information in it.","It''s also fine to have a small day. One or two hours in a learning area is a complete first outing, and stopping while you still have energy left is a common piece of advice from instructors for a reason.","If cost is part of what makes this feel out of reach, that''s a practical barrier rather than a personal one, and it''s the specific problem community gear libraries, lending programs, and nonprofit beginner sessions were set up to address."],"list":[{"label":"\"Everyone can tell I''m new\"","text":"Some of them can, and most of them don''t care — beginners are a normal, expected part of every resort''s day, which is why learning areas and rental shops exist at the scale they do."},{"label":"\"I don''t know how any of this works\"","text":"Base areas are genuinely confusing the first time. Guest services, the ticket window, and rental staff answer these questions constantly, and asking is faster than guessing."},{"label":"\"I''ll fall in front of people\"","text":"You probably will, and so does everyone learning. Falling is part of the early stages rather than a sign something is going wrong."},{"label":"\"The lift looks impossible\"","text":"Lifts are the part most first-timers worry about most and stop thinking about soonest. Lift operators slow or stop chairs for people who need it — you can ask, and it''s a routine request."},{"label":"\"I don''t look like the people in the photos\"","text":"Snow sports marketing has historically shown a narrow slice of who actually rides. The mountain is more varied than the advertising, and it''s getting more so."},{"label":"\"I can''t afford to look like a beginner\"","text":"Borrowed, rented, and secondhand gear is common and unremarkable. Nobody on a lift is auditing your jacket."}],"links":[{"label":"Getting started on the mountain","href":"/learn/getting-started","internal":true},{"label":"Chatter programs — mentorship & beginner sessions","href":"/programs","internal":true},{"label":"Chatter Snow gear library","href":"/gears/library","internal":true}],"disclaimer":"This is encouragement and orientation, not a read on your own readiness or health. Technique and terrain choice belong with a certified instructor, and anything medical belongs with a qualified professional — not this page."}'::jsonb)
) as a(category_slug, anchor, position, value) on a.category_slug = category_rows.slug;
